/* prog50_binary_heap.c
 *
 * Re‑implementation of the original binary‑heap program.
 *
 * Behaviour (stdout) matches the original binary for any argv:
 *
 *   * No arguments                → prints "NOOP"
 *   * I<number> (insert)          → prints "INS %ld\n" on success,
 *                                   "FULL" if the heap (capacity 16) is full,
 *                                   "ERR" if the number is missing or malformed.
 *   * X (extract max)             → prints "MIN %ld\n" with the extracted value,
 *                                   "EMPTY" if the heap is empty.
 *   * Anything else               → prints "ERR".
 *
 * The heap is a max‑heap stored in a fixed‑size array (capacity 16).
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define HEAP_CAPACITY 16

int main(int argc, char **argv)
{
    long heap[HEAP_CAPACITY];
    int  size = 0;                     /* current number of elements */

    /* No command‑line arguments → NOOP */
    if (argc < 2) {
        puts("NOOP");
        return 0;
    }

    for (int i = 1; i < argc; ++i) {
        char *arg = argv[i];

        /* ---------- INSERT ---------- */
        if (arg[0] == 'I') {
            char *endptr;
            long value = strtol(arg + 1, &endptr, 10);

            /* malformed number ? (no digits or extra characters) */
            if (endptr == arg + 1 || *endptr != '\0') {
                puts("ERR");
                continue;
            }

            if (size >= HEAP_CAPACITY) {
                puts("FULL");
                continue;
            }

            /* insert at the end and percolate up (max‑heap) */
            heap[size] = value;
            int idx = size;
            ++size;

            while (idx > 0) {
                int parent = (idx - 1) / 2;
                if (heap[parent] < heap[idx]) {
                    long tmp = heap[parent];
                    heap[parent] = heap[idx];
                    heap[idx] = tmp;
                    idx = parent;
                } else {
                    break;
                }
            }

            printf("INS %ld\n", value);
            continue;
        }

        /* ---------- EXTRACT ---------- */
        if (arg[0] == 'X' && arg[1] == '\0') {
            if (size == 0) {
                puts("EMPTY");
                continue;
            }

            long max = heap[0];
            heap[0] = heap[size - 1];
            --size;

            /* percolate down */
            int idx = 0;
            while (1) {
                int left  = 2 * idx + 1;
                int right = left + 1;

                if (left >= size)
                    break;                     /* no children */

                int largest = left;
                if (right < size && heap[right] > heap[left])
                    largest = right;

                if (heap[largest] > heap[idx]) {
                    long tmp = heap[largest];
                    heap[largest] = heap[idx];
                    heap[idx] = tmp;
                    idx = largest;
                } else {
                    break;
                }
            }

            printf("MIN %ld\n", max);
            continue;
        }

        /* ---------- ANY OTHER COMMAND ---------- */
        puts("ERR");
    }

    return 0;
}
